  PRIMARY KEY  (`ID`),
  KEY `IDX_BuyID` (`BuyID`),
  KEY `IDX_PlayerID` (`PlayerID`),
  KEY `IDX_Name` (`Name`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
