INSERT INTO `MasterLairInfo` VALUES (1104,431,432,0,27,17,1,15,22,22,60,3600,60,1800,60,1103,12,110,3,7,11,'\"How dare you glance at lady¡¯s in bath, get out of here¡­\",\r\n\"Do you have any idea of where you are now?\",\r\n\"Go, my precious children. Go and take them into the eternal darkness.\",\r\n\"Wait for a moment. My force is almost recovered¡­\",\r\n\"My loyal children, go get some blood to fill up my bathtub.\",\r\n\"Show me your loyalty.\",\r\n\"Hmmm¡­ Is that silly or foolish¡­\",\r\n\"Hahaha, you¡¯re still crying for your suvival.\",\r\n\"Cheer up. This is just a start, no need to take a deep breath like that¡­\",\r\n\"You¡¯ll know what Brikolakas taught me isn¡¯t just a magic.\"','\"The Immortal power inside my blood will lead you to death someday.\",\r\n\"Can you hear? Crying of my servants¡­ Our curse will be stuck to your shadow forever.\",\r\n\"The Immortal power inside my blood will lead you to death someday.\",\r\n\"Can you hear? Crying of my servants¡­ Our curse will be stuck to your shadow forever.\",\r\n\"I\'m waking away at this time, but I¡¯ll make a soap with your flesh and blood into my bathtub.\"','\"Who sent you? Are you dogs of Tepez? Son of bitch¡­ with my own hands, I swear I will¡­\",\r\n\"You foolish lost of vampire¡¯s proud, our curse will be following behind your shadow.\",\r\n\"Whose life is flowing in your blood? How foolish and ungrace you are¡­\"','\"Foolish. Shed tears for your weakness in the hell.\",\r\n\"Hahahaha¡­ with this power, you stepped into this place?\",\r\n\"Isn\'t it too late to beg for licking my feet? Hahaha\"'),(1114,433,434,1,22,14,1,15,28,21,60,3600,60,1800,60,1113,77,26,3,7,11,'\"Who are you out there¡­ It is so noisy.\",\r\n\"So far, there are some rats unsensable of fears.\",\r\n\"Whoever interrupts my sleep will cost as much as death.\",\r\n\"Hang on for more. I¡¯ll invite you to my blood festival.\",\r\n\"Hahahaha¡­ Your skin got pale just because of this?\",\r\n\"Hmmm¡­ I wouldn¡¯t have more fun in my life without these dumbs.\",\r\n\"Take a look at your dictionary for ¡®Tolerance¡¯right now.\",\r\n\"The power of our people in Elania will be all mine.\",\r\n\"You will not see myself at all if you fall down like this so soon.\",\r\n\"You may be in trouble if you¡¯re not giving me more fun¡­\"','\"Huh¡­ striking me by the time I¡¯m injured¡­ you¡¯re in a good luck, son.\",\r\n\"Try to find a good place. It will be your tomb side when next time I see you¡­\",\r\n\"I will remember your face. Someday I will hang your butt with a spear¡­\"','\"How come I get caught by betrayers. You¡¯ll see. I won¡¯t be that easy next time.\",\r\n\"Your vows before me were all lies? The immortal being will destroy you.\",\r\n\"Rather than destroying Bathory, how dare you place your sword against me¡­ Your debt will be as much as your death.\"','\"I honor your foolish braveness. I¡¯ll try to kill you without any pains.\",\r\n\"Hahahaha. I¡¯ve got more accessories for my spears.\",\r\n\"How cute you are. You wouldn¡¯t even come if you had a second thought?\"'),(1106,431,432,0,27,17,1,15,22,22,600,3600,300,1800,60,42,180,240,3,7,11,'\"How dare you glance at lady¡¯s in bath, get out of here¡­\",\r\n\"Do you have any idea of where you are now?\",\r\n\"Go, my precious children. Go and take them into the eternal darkness.\",\r\n\"Wait for a moment. My force is almost recovered¡­\",\r\n\"My loyal children, go get some blood to fill up my bathtub.\",\r\n\"Show me your loyalty.\",\r\n\"Hmmm¡­ Is that silly or foolish¡­\",\r\n\"Hahaha, you¡¯re still crying for your suvival.\",\r\n\"Cheer up. This is just a start, no need to take a deep breath like that¡­\",\r\n\"You¡¯ll know what Brikolakas taught me isn¡¯t just a magic.\"','\"The Immortal power inside my blood will lead you to death someday.\",\r\n\"Can you hear? Crying of my servants¡­ Our curse will be stuck to your shadow forever.\",\r\n\"I\'m waking away at this time, but I¡¯ll make a soap with your flesh and blood into my bathtub.\"','\"Who sent you? Are you dogs of Tepez? Son of bitch¡­ with my own hands, I swear I will¡­\",\r\n\"You foolish lost of vampire¡¯s proud, our curse will be following behind your shadow.\",\r\n\"Whose life is flowing in your blood? How foolish and ungrace you are¡­\"','\"Foolish. Shed tears for your weakness in the hell.\",\r\n\"Hahahaha¡­ with this power, you stepped into this place?\",\r\n\"Isn\'t it too late to beg for licking my feet? Hahaha\"'),(1115,433,434,1,22,14,1,15,28,21,600,3600,300,1800,60,52,95,84,3,7,11,'\"Who are you out there¡­ It is so noisy.\",\r\n\"So far, there are some rats unsensable of fears.\",\r\n\"Whoever interrupts my sleep will cost as much as death.\",\r\n\"Hang on for more. I¡¯ll invite you to my blood festival.\",\r\n\"Hahahaha¡­ Your skin got pale just because of this?\",\r\n\"Hmmm¡­ I wouldn¡¯t have more fun in my life without these dumbs.\",\r\n\"Take a look at your dictionary for ¡®Tolerance¡¯right now.\",\r\n\"The power of our people in Elania will be all mine.\",\r\n\"You will not see myself at all if you fall down like this so soon.\",\r\n\"You may be in trouble if you¡¯re not giving me more fun¡­\"','\"Huh¡­ striking me by the time I¡¯m injured¡­ you¡¯re in a good luck, son.\",\r\n\"Try to find a good place. It will be your tomb side when next time I see you¡­\",\r\n\"I will remember your face. Someday I will hang your butt with a spear¡­\"','\"How come I get caught by betrayers. You¡¯ll see. I won¡¯t be that easy next time.\",\r\n\"Your vows before me were all lies? The immortal being will destroy you.\",\r\n\"Rather than destroying Bathory, how dare you place your sword against me¡­ Your debt will be as much as your death.\"','\"I honor your foolish braveness. I¡¯ll try to kill you without any pains.\",\r\n\"Hahahaha. I¡¯ve got more accessories for my spears.\",\r\n\"How cute you are. You wouldn¡¯t even come if you had a second thought?\"');
